import { Accessor, createEffect, createMemo, createSignal, For, JSX } from "solid-js";

import { ScrollArea, ScrollAreaBaseProps } from "#core/ui-next/components/scroll-area.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface VirtualScrollAreaProps<T extends readonly unknown[], U extends JSX.Element> {
	/** The function which instantiates each item */
	children: (item: T[number], index: Accessor<number>) => U;
	/** The collection of items in the list */
	each: T;

	itemHeight: number;

	itemWidth?: number;

	scrollArea?: ScrollAreaBaseProps;

	class?: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function VirtualScrollAreaComponent<T extends readonly any[], U extends JSX.Element>(
	props: VirtualScrollAreaProps<T, U>,
) {
	const [visibleItems, setVisibleItems] = createSignal<T>([] as unknown as T);
	const [visibleItemsTop, setVisibleItemsTop] = createSignal(0);
	const [scrollPercent, setScrollPercent] = createSignal(0);
	const [clientWidth, setClientWidth] = createSignal(0);
	const [clientHeight, setClientHeight] = createSignal(0);

	const itemsPerRow = createMemo(() => {
		return props.itemWidth && clientWidth() ? Math.floor(clientWidth() / props.itemWidth) : 1;
	});

	const numRows = createMemo(() => Math.ceil(props.each.length / itemsPerRow()));
	const rowsHeight = createMemo(() => numRows() * props.itemHeight);

	createEffect(() => {
		const numVisibleRows = Math.floor((clientHeight() ?? 1) / props.itemHeight) + 2;
		const unitScroll = scrollPercent() / 100;
		const numRowItems = itemsPerRow();
		const firstVisibleRow = Math.max(0, Math.floor((numRows() - numVisibleRows) * unitScroll));
		const firstItem = firstVisibleRow * numRowItems;
		const top = firstVisibleRow * props.itemHeight;
		const lastItem = Math.min(props.each.length, firstItem + numVisibleRows * numRowItems);
		const items = props.each.slice(firstItem, lastItem);

		setVisibleItemsTop(top);
		setVisibleItems(() => items as unknown as T);
	});

	return (
		<ScrollArea
			{...props.scrollArea}
			class={props.class}
			setScroll={setScrollPercent}
			setClientHeight={setClientHeight}
			setClientWidth={setClientWidth}
		>
			<div
				class={"relative w-full"}
				style={{ height: `${rowsHeight()}px` }}
			>
				<div
					class={`absolute ${props.itemWidth ? "flex flex-row flex-wrap w-full" : ""}`}
					style={{
						top: `${visibleItemsTop()}px`,
					}}
				>
					<For each={visibleItems()}>{props.children}</For>
				</div>
			</div>
		</ScrollArea>
	);
}

/**
 * A vertically scrollable area.
 * ```tsx
 * <VirtualScrollArea itemHeight={200} each={() => items()}>
 *   {(item) => <ItemTemplate {...item} />}
 * </VirtualScrollArea>
 * ```
 * Default implementation: {@link VirtualScrollAreaComponent}
 * @param {VirtualScrollAreaProps} props See {@link VirtualScrollAreaProps} for a full list of properties
 */
export const VirtualScrollArea = ComponentRegistry.register({
	name: "VirtualScrollArea",
	createInstance: VirtualScrollAreaComponent,
});
